            print(f"  {t[:16]} Allergy {rid}: {r['code']['text']} reaction={[x.get('description') or x.get('manifestation',[{}])[0].get('text') for x in r.get('reaction',[])]}")
        elif rt=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            s=spec.get(sp)
            lbl=''
            if s:
                lm,ld,ln=ext(s,'label-mrn'),ext(s,'label-dob'),ext(s,'label-name')
                lbl=f"spec={sp} label[{ln}|{lm}|{ld}]"
                if lm!=p['identifier'][0]['value'] or ld!=p['birthDate']: lbl+=' **LABEL_MISMATCH**'
            a=acc.get((r.get('identifier') or [{}])[0].get('value'))
            ac=''
            if a:
                am,ad,an=ext(a,'patient-mrn'),ext(a,'patient-dob'),ext(a,'patient-name')
                ac=f" accn={a['id']}[{an}|{am}|{ad}] rec={ext(a,'received')} by={a.get('author',{}).get('display')}"
                if s and (am!=ext(s,'label-mrn') or ad!=ext(s,'label-dob')): ac+=' **ACCN_MISMATCH**'
            note=' | '.join(n['text'] for n in r.get('note',[]))
            print(f"  {t[:16]} Obs {rid}: {r['code']['text']} coll={r.get('effectiveDateTime','')[:16]} status={r['status']} val={r.get('valueString')} issued={r.get('issued','')[:16]} {lbl}{ac}" + (f" NOTE: {note}" if note else ''))
        elif rt=='Specimen':
            pass
        elif rt=='MedicationAdministration':
            note=' | '.join(n['text'] for n in r.get('note',[]))
            print(f"  {t[:16]} MedAdmin {rid}: {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} status={r['status']} eff={r.get('effectiveDateTime','')[:16]} by={r.get('performer',[{}])[0].get('actor',{}).get('display')}" + (f" NOTE: {note}" if note else ''))
        elif rt=='MedicationDispense':
            note=' | '.join(n['text'] for n in r.get('note',[]))
            print(f"  {t[:16]} MedDisp {rid}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver','')[:16]} instr={[d.get('text') for d in r.get('dosageInstruction',[])]}" + (f" NOTE: {note}" if note else ''))
        elif rt=='DocumentReference':
            print(f"  {t[:16]} Doc {rid} [{r['type']['text']}] by {[a['display'] for a in r.get('author',[])]} role={ext(r,'author-role')}")
            for line in r['description'].split('\n'):
                if line.strip(): print('        '+line)
        elif rt=='Task':
            print(f"  REQUEST {rid}: {r['code']['coding'][0]['code']} focus={r['focus']['reference']} :: {r['description']}")
