    if it['disposition']=='cannot_determine' and not it['missing_evidence']: print('MISSCODE',it); bad+=1
    if it['disposition']!='cannot_determine' and it['missing_evidence']: print('EXTRACODE',it); bad+=1
    for e in it['evidence']:
        if e not in allres: print('MISSING',it['patient'],it['issue'],e); bad+=1
    if not (1<=len(it['evidence'])<=30): print('EVLEN',it['patient'],len(it['evidence'])); bad+=1
    if not it['explanation'] or len(it['explanation'])>4000: print('EXPL',it['patient']); bad+=1
print('bad',bad,'items',len(ITEMS))
print(collections.Counter((i['issue'],i['disposition']) for i in ITEMS))
# request coverage
reqs={}
for t in load('Task'):
    if t.get('status')=='requested': reqs[(t['focus']['reference'][14:],t['code']['coding'][0]['code'])]=t['id']
have=set((i['episode'],i['issue']) for i in ITEMS)
for k,v in reqs.items():
    if k not in have: print('REQ NOT ANSWERED',k,v)
